#ifndef DATASET_H
#define DATASET_H

#include <stdint.h>

/*
 * Pre-generated input data, compiled into the executable so that every run of
 * every version works on exactly the same values and no time is spent
 * generating them at runtime.
 *
 * The definitions are generated by scripts/generate_dataset.py
 * (run automatically by `make`).
 */

// Values inserted into the tree
extern uint32_t dataset_nodes[];
extern const int dataset_nodes_count;

// Values to search for in the tree
extern uint32_t dataset_queries[];
extern const int dataset_queries_count;

#endif // DATASET_H
